import { defineConfig } from 'cypress'

export default defineConfig({
  e2e: {
    setupNodeEvents(on) {
      on('task', {
        seedUsers({ count }) {
          return Array.from({ length: count }, (_, id) => ({ id }))
        },
      })
    },
  },
})

